# Parse length to seconds across all sources
import re

def to_seconds(s):
    if s is None or (isinstance(s, float) and pd.isna(s)):
        return None
    s = str(s).strip()
    if s == '' or s.lower() in ('nan','unk.','unknown','n.a.'):
        return None
    # "Xm Ysec"
    m = re.match(r'^(\d+)\s*m\s*(\d+)\s*sec\s*$', s)
    if m:
        return int(m.group(1))*60 + int(m.group(2))
    # "Xm Ysec." or similar
    m = re.match(r'^(\d+)\s*m\s*$', s)
    if m:
        return int(m.group(1))*60
    # MM:SS
    m = re.match(r'^(\d+):(\d+)$', s)
    if m:
        return int(m.group(1))*60 + int(m.group(2))
    # H:MM:SS
    m = re.match(r'^(\d+):(\d+):(\d+)$', s)
    if m:
        return int(m.group(1))*3600 + int(m.group(2))*60 + int(m.group(3))
    # float seconds OR ms OR minutes
    try:
        v = float(s)
    except ValueError:
        return None
    # determine units. Heuristics:
    # - If integer-like and very large (>= 30000) — milliseconds
    if v >= 20000:
        return v/1000.0
    # - If small with decimal (likely minutes.fraction) — minutes
    if '.' in s and v < 60:
        return v*60
    # - Integer seconds
    return v

