# Build a UnionFind-based entity resolution.
# Edges: same (t2, a2) where both non-empty; or same (t2, al2) where one a2 is empty.

import collections

class UF:
    def __init__(self, n):
        self.p = list(range(n))
    def f(self, x):
        while self.p[x] != x:
            self.p[x] = self.p[self.p[x]]
            x = self.p[x]
        return x
    def u(self, a, b):
        ra, rb = self.f(a), self.f(b)
        if ra != rb:
            self.p[ra] = rb

